<template><view class="page"><view class="profile-top"><view class="between"><text class="section-kicker">A LITTLE ABOUT YOU</text><text class="small muted">青禾校园</text></view><view class="row user" @click="signIn"><view class="avatar">禾</view><view><view class="title">{{state.token?me.nickname||'校园食客':'你好，校园食客'}}</view><view class="subtitle">{{state.token?'好好吃饭，是对生活的热爱':'点击登录，开启你的美味日常'}} ›</view></view></view><view class="assets"><view @click="go('benefits/index')"><text class="number">{{me.coupons||0}}</text><text>优惠券</text></view><view @click="go('benefits/index')"><text class="number">{{me.points||0}}</text><text>我的积分</text></view><view @click="orders"><text class="number">♡</text><text>美味记录</text></view></view></view><view class="content"><view class="benefit-banner" @click="go('benefits/index')"><text class="crown">♛</text><view><view class="bold">青禾有礼 · 每餐都有小惊喜</view><view class="tiny">签到攒积分，兑换专属优惠</view></view><text>›</text></view><view class="task-row"><view class="card" @click="checkin"><text class="task-icon">☑</text><view class="bold">{{me.checkedIn?'今日已签到':'每日签到'}}</view><view class="subtitle small">每天领取10积分</view></view><view class="card" @click="go('benefits/index')"><text class="task-icon gold">◉</text><view class="bold">积分好礼</view><view class="subtitle small">小积分，大满足</view></view></view><view class="card tools"><view class="bold">我的服务</view><view class="tool-grid"><view v-for="t in tools" :key="t.name" @click="go(t.path)"><text class="tool-icon">{{t.icon}}</text><text>{{t.name}}</text></view></view></view><view class="card between" @click="go('help/index')"><view><view class="bold">想说的话，我们都在听</view><view class="subtitle small">订单问题 / 意见反馈 / 帮助中心</view></view><text class="support-icon">☏</text></view><view v-if="state.token" class="logout" @click="logout">退出当前账号</view><view class="slogan">青禾校园 · 让校园生活多一点滋味</view></view><BottomNav active="profile"/></view></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import BottomNav from '../../components/BottomNav.vue';import {state,request,login,ensureLogin,go,toast,confirm,clearCart} from '../../lib/api';const me=ref({});const tools=[{name:'地址管理',icon:'⌖',path:'addresses/index'},{name:'我的优惠',icon:'▧',path:'benefits/index'},{name:'意见反馈',icon:'✎',path:'help/index?tab=feedback'},{name:'帮助中心',icon:'▤',path:'help/index'},{name:'消息中心',icon:'♧',path:'help/index?tab=messages'},{name:'联系客服',icon:'☏',path:'help/index?tab=feedback'}];async function load(){if(state.token)try{me.value=await request('/me')}catch{}else me.value={}}async function signIn(){if(state.token)return;try{await login();load()}catch(e){toast(e.message)}}async function checkin(){try{await ensureLogin();await request('/checkin','POST');toast('签到成功，积分 +10');load()}catch{}}function orders(){uni.reLaunch({url:'/pages/orders/index'})}async function logout(){if(!await confirm('确认退出？演示账号退出后不会自动恢复，请保留当前登录以继续体验。'))return;state.token='';uni.removeStorageSync('food-token');clearCart();me.value={}}onShow(load);
</script>
<style scoped>.profile-top{padding:50rpx 34rpx 35rpx;padding-top:calc(50rpx + env(safe-area-inset-top));background:linear-gradient(120deg,#ebeed6,#f7f7e9)}.user{margin:40rpx 0}.avatar{background:#dde6c8;border:6rpx solid #fff8;width:118rpx;height:118rpx;display:flex;align-items:center;justify-content:center;border-radius:50%;font-size:55rpx;color:#667e4c;margin-right:24rpx}.user .title{font-size:35rpx}.user .subtitle{font-size:23rpx}.assets{display:flex;justify-content:space-around}.assets view{display:flex;flex-direction:column;align-items:center;color:#879277;font-size:24rpx;gap:9rpx}.number{font-size:42rpx;font-weight:700;color:#526946}.benefit-banner{display:flex;align-items:center;gap:18rpx;background:linear-gradient(110deg,#e8ddbb,#f2e9cf);color:#897345;border-radius:21rpx;padding:28rpx 23rpx;font-size:25rpx;margin-bottom:28rpx}.benefit-banner .tiny{margin-top:9rpx}.benefit-banner>text:last-child{margin-left:auto;font-size:40rpx}.crown{font-size:51rpx}.task-row{display:flex;gap:22rpx}.task-row .card{width:50%;position:relative;padding:33rpx 23rpx}.task-icon{color:#739974;font-size:40rpx;display:block;margin-bottom:17rpx}.gold{color:#c5a35c}.tool-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:38rpx 16rpx;margin-top:34rpx}.tool-grid view{display:flex;align-items:center;flex-direction:column;gap:14rpx;font-size:24rpx;color:#859279}.tool-icon{font-size:44rpx;color:#6c8b63;background:#f0f4e9;width:70rpx;height:70rpx;text-align:center;border-radius:22rpx}.support-icon{font-size:60rpx;color:#7f9a71}.logout{text-align:center;color:#99a58c;font-size:23rpx;margin:30rpx}.slogan{text-align:center;font-size:20rpx;letter-spacing:2rpx;color:#b0b9a5;margin-top:40rpx}</style>
